import { FunctionalComponent, Fragment } from 'preact';
import { useSelector } from 'react-redux';
import { selectTriviaState } from './slice';

import styles from './styles.module.scss';

import Shell from './components/Shell';
import TriviaDialog from './components/TriviaDialog';
import CorrectAnswerDialog from './components/CorrectAnswer';
import IncorrectAnswerDialog from './components/IncorrectAnswer';

const DIALOG_BY_TYPE = {
  TRIVIA: TriviaDialog,
  CORRECT_ANSWER: CorrectAnswerDialog,
  INCORRECT_ANSWER: IncorrectAnswerDialog,
};

const Trivia: FunctionalComponent = () => {
  const { dialogMode } = useSelector(selectTriviaState);

  const Dialog = DIALOG_BY_TYPE[dialogMode];

  return (
    <Fragment>
      <Shell />
      {Dialog && (
        <div className={styles.backdrop}>
          <Dialog />
        </div>
      )}
    </Fragment>
  );
};

export default Trivia;
